  ["ch <- x sends. x := <-ch receives. Same operator, different place."] = "ch <- x 发送。x := <-ch 接收。同一个运算符，位置不同。",
  ["chan is a typed pipe. <- sends and receives. close tells receivers to stop."] = "chan 是带类型的管道。<- 用于发送和接收。close 告诉接收方停止。",
  ["chan struct{} plus close is the cheapest done signal. context.Done() returns one."] = "chan struct{} 加 close 是最省的完成信号。context.Done() 返回的就是它。",
  ["cheapest := ___(muffin, hash, coffee)   // built-in\n"] = "cheapest := ___(muffin, hash, coffee)   // 内置函数\n",
  ["clear(m) deletes every key. Before 1.21 you looped with delete."] = "clear(m) 删除所有键。1.21 之前要用 delete 循环删。",
  ["close(ch). range ch stops when the channel is closed."] = "close(ch)。channel 关闭后 range ch 就会停止。",
  ["close(jobs) is the shutdown signal: every worker's range loop drains and exits."] = "close(jobs) 是关停信号：每个 worker 的 range 循环取空后退出。",
  ["comparable for map keys and ==. any allows everything but promises nothing."] = "comparable 用于 map 键和 ==。any 允许一切，但什么也不保证。",
  ["const (\n    Muffin = ___       // 0\n    Hash               // 1\n    Coffee             // 2\n)\n"] = "const (\n    Muffin = ___       // 0\n    Hash               // 1\n    Coffee             // 2\n)\n",
  ["const opens = 6. The lift knows when breakfast starts."] = "const opens = 6。电梯知道早餐几点开始。",
  ["context carries deadlines and cancel. go test runs Test* in _test.go."] = "context 携带截止时间和取消。go test 运行 _test.go 里的 Test*。",
  ["context.Background() then WithCancel. Always defer cancel()."] = "context.Background() 然后 WithCancel。永远要 defer cancel()。",
  ["continue skips one round; break ends the loop."] = "continue 跳过一轮；break 结束循环。",
  ["ctx := context.___()\nctx, cancel := context.WithCancel(ctx)\ndefer cancel()\n"] = "ctx := context.___()\nctx, cancel := context.WithCancel(ctx)\ndefer cancel()\n",
  ["ctx, cancel := context.___(ctx, 2*time.Second)\ndefer cancel()          // always\n"] = "ctx, cancel := context.___(ctx, 2*time.Second)\ndefer cancel()          // 永远要写\n",
  ["ctx.Done() closes on cancel or deadline; ctx.Err() says which one."] = "ctx.Done() 在取消或到期时关闭；ctx.Err() 告诉你是哪一种。",
  ["default: runs when every channel would block. The till stays free."] = "default: 在所有 channel 都会阻塞时运行。收银机不被占住。",
  ["defer captures its arguments now, not later. What does this print?"] = "defer 立刻捕获参数，而不是之后。这会打印什么？",
  ["defer evaluates arguments immediately. defer func() { fmt.Println(x) }() would print 2."] = "defer 立即求值参数。defer func() { fmt.Println(x) }() 会打印 2。",
  ["defer f.Close(). The drawer shuts even if Pay fails."] = "defer f.Close()。即使 Pay 失败，抽屉也会关上。",
  ["defer func() {\n    if r := ___(); r != nil {\n        // saved the till\n    }\n}()\n"] = "defer func() {\n    if r := ___(); r != nil {\n        // 收银机保住了\n    }\n}()\n",
  ["delete(m, k) removes it. Maps grow by assignment, shrink by this."] = "delete(m, k) 删除它。map 靠赋值增长，靠它缩小。",
  ["delete(m, key). Safe if the key is already gone."] = "delete(m, key)。键已经不在也安全。",
  ["done := make(chan ___)   // zero bytes per value\ngo func() {\n    cook()\n    close(done)\n}()\n<-done\n"] = "done := make(chan ___)   // 每个值零字节\ngo func() {\n    cook()\n    close(done)\n}()\n<-done\n",
  ["error is an interface. Check err != nil. defer runs when the function returns."] = "error 是一个 interface。检查 err != nil。defer 在函数返回时执行。",
  ["error is interface{ Error() string }. Your own types can carry data."] = "error 就是 interface{ Error() string }。你自己的类型可以携带数据。",
